// All points a force arrow or a marker can sit on: the anatomical landmarks generated by the bone pipeline, plus
// hand-level points for the exercises (where the other hand resists) and the centres of the held objects.
import rigJson from './rigdata.json';
import type { Landmark, LandmarkId, RigData } from './anatomy';
import { PROP_CENTRE } from './props';

const RIG = rigJson as unknown as RigData;

export type ExtraLandmarkId =
  | 'hand_dorsal' | 'hand_palmar' | 'hand_radial' | 'hand_ulnar'
  | 'prop_dumbbell' | 'prop_hammer_head' | 'prop_bottle';
export type AnyLandmarkId = LandmarkId | ExtraLandmarkId;

// p = on the bone, skin = on the skin, n = outward. Rig frame: +X ulnar, +Y distal, +Z dorsal.
const EXTRA: Record<ExtraLandmarkId, Landmark> = {
  hand_dorsal: { frame: 'mid', p: [-0.008, 0.055, 0.006], n: [0, 0, 1], skin: [-0.008, 0.055, 0.012] },
  hand_palmar: { frame: 'mid', p: [-0.008, 0.055, -0.016], n: [0, 0, -1], skin: [-0.008, 0.055, -0.024] },
  hand_radial: { frame: 'mid', p: [-0.036, 0.062, -0.006], n: [-1, 0, 0], skin: [-0.043, 0.062, -0.006] },
  hand_ulnar: { frame: 'mid', p: [0.026, 0.052, -0.012], n: [1, 0, 0], skin: [0.034, 0.052, -0.012] },
  prop_dumbbell: { frame: 'mid', p: PROP_CENTRE.dumbbell, n: [0, 0, -1] },
  prop_hammer_head: { frame: 'mid', p: PROP_CENTRE.hammer, n: [0, 0, -1] },
  prop_bottle: { frame: 'mid', p: PROP_CENTRE.bottle, n: [0, 0, -1] },
};

export const LANDMARKS: Record<AnyLandmarkId, Landmark> = { ...RIG.landmarks, ...EXTRA };
